abstract class Branch {
    abstract String openSavingsAccount(Customer customer);
    abstract double issueVehicleLoan(String vehicleType, Customer customer);
    abstract double issueHouseLoan(Customer customer);
    abstract double issueGoldLoan(Customer customer);
}

public interface IBank {
    int CAUTION_MONEY = 2000; // public static final by default

    String createAccount(Customer customer); // public abstract
    double issueVehicleLoan(String vehicleType, Customer customer);
    double issueHouseLoan(Customer customer);
    double issueGoldLoan(Customer customer);
}

public interface IBankNew {
    boolean applyforCreditCard(Customer customer);
}

public class Customer {
    private String name;
    private String customerId;

    public String getName() { return name; }
    public void setName(String name) { this.name = name; }

    public String getCustomerId() { return customerId; }
    public void setCustomerId(String customerId) { this.customerId = customerId; }
}

public class MumbaiOffice implements IBank, IBankNew {
    public String createAccount(Customer customer) {
        return "Acc12345"; // simulated account creation
    }

    public double issueVehicleLoan(String vehicleType, Customer customer) {
        return vehicleType.equals("bike") ? 100000 : 500000;
    }

    public double issueHouseLoan(Customer customer) {
        return 200000;
    }

    public double issueGoldLoan(Customer customer) {
        return 500000;
    }

    public boolean applyforCreditCard(Customer customer) {
        return true;
    }
}

public class Execute {
    public static void main(String[] args) {
        IBank bank = new MumbaiOffice(); // interface reference
        Customer customer = new Customer();
        customer.setCustomerId("cust1001");
        customer.setName("Ajay");

        String accountNumber = bank.createAccount(customer);
        System.out.println("Account number is... " + accountNumber);

        System.out.println("Gold loan amount is... " + bank.issueGoldLoan(customer));
        System.out.println("House loan amount is... " + bank.issueHouseLoan(customer));
        System.out.println("Vehicle loan amount is... " + bank.issueVehicleLoan("bike", customer));
        System.out.println("Caution money is... " + IBank.CAUTION_MONEY);

        // Interface reference for credit card
        IBankNew nbank = new MumbaiOffice();
        boolean issueCard = nbank.applyforCreditCard(customer);
        System.out.println("Credit card is available... " + issueCard);
    }
}

